import torch

def apply_causal_mask_good(scores: torch.Tensor) -> torch.Tensor:
    seq_len = scores.size(-1)
    # FIX: Mask strictly upper-triangular elements (future tokens j > i)
    mask = torch.triu(torch.ones(seq_len, seq_len, device=scores.device), diagonal=1).bool()
    return scores.masked_fill(mask, -1e9)

